"use client";

/*
 * SVG displacement technique inspired by "Wobble" by wehwayne2:
 * https://codepen.io/wehwayne2/pen/pvgajXY
 *
 * This is an independent React implementation built from the platform SVG
 * primitives feTurbulence and feDisplacementMap. The referenced Pen does not
 * publish an explicit source-code license.
 */

import { forwardRef, useId, useInsertionEffect, type HTMLAttributes, type ReactNode } from "react";

export interface WobbleProps extends Omit<HTMLAttributes<HTMLSpanElement>, "children"> {
  /** Content receiving the SVG displacement filter. */
  children: ReactNode;
  /** Displacement distance in SVG units. */
  strength?: number;
  /** Fractal-noise density. Smaller values create broader bends. */
  frequency?: number;
  /** Fractal-noise detail passes. Higher values cost more to render. */
  octaves?: number;
  /** Stable variation of the generated noise field. */
  seed?: number;
  /** Extra filter region around the target, as a percentage of its bounds. */
  filterMargin?: number;
  /** Keeps the wrapper in place while removing the visual filter. */
  disabled?: boolean;
}

const STYLE_ID = "boring-ui-wobble-styles";

const STYLE_TEXT = `
.bui-wobble {
  position: relative;
  display: inline-block;
}

.bui-wobble__defs {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
}

.bui-wobble__content {
  display: inherit;
}

@media (forced-colors: active), print {
  .bui-wobble__content {
    filter: none !important;
  }
}
`;

function clamp(value: number, minimum: number, maximum: number) {
  return Math.min(Math.max(value, minimum), maximum);
}

function finiteOr(value: number, fallback: number) {
  return Number.isFinite(value) ? value : fallback;
}

function joinClassNames(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(" ");
}

function useWobbleStyles() {
  useInsertionEffect(() => {
    if (typeof document === "undefined" || document.getElementById(STYLE_ID)) return;

    const element = document.createElement("style");
    element.id = STYLE_ID;
    element.textContent = STYLE_TEXT;
    document.head.appendChild(element);
  }, []);
}

export const Wobble = forwardRef<HTMLSpanElement, WobbleProps>(function Wobble(
  {
    children,
    strength = 2,
    frequency = 0.05,
    octaves = 2,
    seed = 0,
    filterMargin = 20,
    disabled = false,
    className,
    ...props
  },
  ref,
) {
  useWobbleStyles();
  const generatedId = useId();
  const filterId = `bui-wobble-${generatedId.replaceAll(":", "")}`;
  const safeStrength = clamp(finiteOr(strength, 2), 0, 40);
  const safeFrequency = clamp(finiteOr(frequency, 0.05), 0.001, 0.5);
  const safeOctaves = clamp(Math.round(finiteOr(octaves, 2)), 1, 5);
  const safeSeed = clamp(Math.round(finiteOr(seed, 0)), 0, 999);
  const safeMargin = clamp(finiteOr(filterMargin, 20), 0, 200);

  return (
    <span
      {...props}
      ref={ref}
      className={joinClassNames("bui-wobble", className)}
      data-wobble=""
      data-disabled={disabled ? "true" : "false"}
    >
      <svg className="bui-wobble__defs" width="0" height="0" aria-hidden="true" focusable="false">
        <defs>
          <filter
            id={filterId}
            x={`${-safeMargin}%`}
            y={`${-safeMargin}%`}
            width={`${100 + safeMargin * 2}%`}
            height={`${100 + safeMargin * 2}%`}
            colorInterpolationFilters="sRGB"
          >
            <feTurbulence
              type="fractalNoise"
              baseFrequency={safeFrequency}
              numOctaves={safeOctaves}
              seed={safeSeed}
              result="wobble-noise"
            />
            <feDisplacementMap
              in="SourceGraphic"
              in2="wobble-noise"
              scale={safeStrength}
              xChannelSelector="R"
              yChannelSelector="G"
            />
          </filter>
        </defs>
      </svg>

      <span
        className="bui-wobble__content"
        data-wobble-content=""
        style={{ filter: disabled ? "none" : `url("#${filterId}")` }}
      >
        {children}
      </span>
    </span>
  );
});

Wobble.displayName = "Wobble";
